<script setup lang="ts">
import {onHide as onPageHide} from "@dcloudio/uni-app"
import {abandonLogin as cancelPageLogin} from "../../features/auth"
onPageHide(cancelPageLogin)

import LoginSheet from "../../components/LoginSheet.vue"

import { ref,computed } from 'vue'
import { onLoad,onReachBottom } from '@dcloudio/uni-app'
import { request,navigate,token,event,type Row } from '../../api/platform'
import type { ArticleCard,ArticlePage } from '../../types/api'
import {contentTypes,loadContentTypes} from '../../features/catalog'
import PageState from '../../components/PageState.vue'
import DiscoveryCards from '../../components/DiscoveryCards.vue'
const q=ref(''),categoryIds=ref<string[]>([]),typeCodes=ref<string[]>([]),labelIds=ref<string[]>([]),keywordIds=ref<string[]>([]),expired=ref(false),sheet=ref(false),searched=ref(false),busy=ref(false),error=ref(''),cursor=ref(''),snapshot=ref(''),total=ref(0),echoOnly=ref(false)
const draft=ref({typeCodes:[] as string[],categoryIds:[] as string[],labelIds:[] as string[],keywordIds:[] as string[],expired:false})
function openFilter(){draft.value={typeCodes:[...typeCodes.value],categoryIds:[...categoryIds.value],labelIds:[...labelIds.value],keywordIds:[...keywordIds.value],expired:expired.value};sheet.value=true}
function apply(){typeCodes.value=[...draft.value.typeCodes];categoryIds.value=[...draft.value.categoryIds];labelIds.value=[...draft.value.labelIds];keywordIds.value=[...draft.value.keywordIds];expired.value=draft.value.expired;void search()}
const categories=ref<Row[]>([]),labels=ref<Row[]>([]),keywords=ref<Row[]>([]),history=ref<Row[]>([]),hot=ref<Row[]>([]),popular=ref<Row[]>([]),items=ref<ArticleCard[]>([])
const types=computed<{code:string;name:string}[]>(()=>[{code:'',name:'全部'},...contentTypes.value.map(t=>({code:t.code,name:t.name}))])
function toggleContentType(code:string){draft.value.typeCodes=draft.value.typeCodes.includes(code)?draft.value.typeCodes.filter(x=>x!==code):[...draft.value.typeCodes,code]}
function toggleBoard(id:string){draft.value.categoryIds=draft.value.categoryIds.includes(id)?draft.value.categoryIds.filter(x=>x!==id):[...draft.value.categoryIds,id];draft.value.labelIds=draft.value.labelIds.filter(id=>labels.value.some(l=>l.id===id&&draft.value.categoryIds.includes(l.categoryId)))}
const visibleLabels=computed(()=>labels.value.filter(l=>draft.value.categoryIds.includes(l.categoryId)))
async function loadHistory(){history.value=uni.getStorageSync('yunji.search.history')||[]}
function recordHistory(query:string){history.value=[{query},...history.value.filter((h:Row)=>h.query!==query)].slice(0,20);uni.setStorageSync('yunji.search.history',history.value)}
function removeHistory(query:string){history.value=history.value.filter((h:Row)=>h.query!==query);uni.setStorageSync('yunji.search.history',history.value)}
function clear(){history.value=[];uni.removeStorageSync('yunji.search.history')}
function toggle(id:string){draft.value.labelIds=draft.value.labelIds.includes(id)?draft.value.labelIds.filter(x=>x!==id):[...draft.value.labelIds,id]}
function toggleKeyword(id:string){draft.value.keywordIds=draft.value.keywordIds.includes(id)?draft.value.keywordIds.filter(x=>x!==id):[...draft.value.keywordIds,id]}
async function search(reset=true){if(busy.value)return;busy.value=true;error.value='';sheet.value=false;try{
 if(reset){cursor.value='';snapshot.value='';items.value=[];searched.value=true;if(q.value.trim())recordHistory(q.value.trim())}
 const textQuery=echoOnly.value?'':q.value.trim()
 let query='includeExpired='+expired.value+'&pageSize=20'+(textQuery?'&q='+encodeURIComponent(textQuery):'')
 for(const [key,value] of Object.entries({categoryIds:categoryIds.value.join(','),contentType:typeCodes.value.join(','),labelIds:labelIds.value.join(','),keywordIds:keywordIds.value.join(','),cursor:cursor.value,snapshotAt:snapshot.value}))if(value)query+='&'+key+'='+encodeURIComponent(value)
 const page=await request<ArticlePage>('GET','/api/v1/articles/search?'+query);items.value.push(...page.items);cursor.value=page.nextCursor||'';snapshot.value=page.snapshotAt;total.value=page.total
 if(reset)await event('FILTER',undefined,{q:textQuery,categoryIds:categoryIds.value,labels:labelIds.value,includeExpired:expired.value})
 }catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function missing(){if(!token()){navigate('login');return}uni.showModal({title:'缺失信息申报',editable:true,placeholderText:'请描述缺少的内容或提供来源',success:async r=>{if(r.confirm&&r.content)try{await request('POST','/api/v1/me/feedback',{description:'缺失信息申报：'+r.content});uni.showToast({title:'已提交'})}catch(e){error.value=(e as Error).message}}})}
onLoad(async options=>{try{await loadContentTypes();popular.value=await request('GET','/api/v1/search/popular');if(options?.echo){q.value=decodeURIComponent(String(options.echo));echoOnly.value=true}else{q.value=String(options?.q||'')}categoryIds.value=options?.categoryId?[String(options.categoryId)]:[];if(options?.keywordId)keywordIds.value=[String(options.keywordId)];if(options?.labelId)labelIds.value=[String(options.labelId)];[categories.value,labels.value,keywords.value,hot.value]=await Promise.all([request('GET','/api/v1/catalog/categories'),request('GET','/api/v1/catalog/labels'),request('GET','/api/v1/catalog/keywords?limit=100'),request('GET','/api/v1/search/hot')]);await loadHistory();if(q.value||categoryIds.value.length||keywordIds.value.length||labelIds.value.length)await search()}catch(e){error.value=(e as Error).message}})
onReachBottom(()=>{if(cursor.value)void search(false)})
</script>
<template><view class="page"><view class="search-row"><input v-model="q" :placeholder="hot[0]?.name||'输入关键字或标签以搜索'" maxlength="100" confirm-type="search" @input="echoOnly=false" @confirm="search()"/><button role="button" :disabled="busy" @click="search()">搜索</button><button role="button" class="quiet" @click="openFilter">筛选</button></view><PageState :busy="busy" :error="error" @retry="search()"/><template v-if="!searched"><view class="section-head"><text class="section-title">历史搜索</text><button role="button" class="quiet" @click="clear">清空</button></view><view class="actions"><view v-for="h in history" :key="h.query" class="actions"><button role="button" class="quiet" @click="q=h.query;search()">{{ h.query }}</button><button role="button" class="quiet" :aria-label="'删除搜索记录'+h.query" @click="removeHistory(h.query)">×</button></view></view><text v-if="!history.length" class="muted">暂无搜索历史</text><view class="section-head"><text class="section-title">热搜榜</text></view><text class="muted small">近七天用户搜索过的公开关键词</text><button role="button" v-for="(h,i) in hot" :key="h.id" class="card" @click="q=h.name;search()">{{ i+1 }} · {{ h.name }}</button><view v-if="!hot.length" class="empty">搜索数据积累中</view><view class="section-head"><text class="section-title">热门资讯</text></view><view v-for="a in popular" :key="a.id" class="list-item" @click="navigate('article','?id='+a.id)"><text>{{ a.title }}</text></view></template><template v-else><view class="section-head"><text>找到 {{ total }} 条资讯</text><text class="muted">{{ expired?'含过期历史':'当前有效与未开始' }}</text></view><DiscoveryCards :items="items"/><view v-if="!items.length&&!busy" class="empty">暂无匹配内容<button role="button" class="quiet" @click="missing">缺失信息申报</button></view><button role="button" v-if="cursor" :disabled="busy" class="secondary" @click="search(false)">加载更多</button></template><view v-if="sheet" class="sheet-mask" @click="sheet=false"><view class="filter-sheet" @click.stop><view class="row"><text class="section-title">筛选资讯</text><button role="button" class="quiet" @click="sheet=false">关闭</button></view><text class="field-label">信息类型</text><view class="actions"><button role="button" v-for="t in types" :key="t.code" :class="!draft.typeCodes.length?'':(t.code&&draft.typeCodes.includes(t.code)?'':'quiet')" @click="t.code===''?draft.typeCodes=[]:toggleContentType(t.code)">{{ t.name }}</button></view><text class="field-label">板块（可多选）</text><view class="tag-grid"><button role="button" :class="!draft.categoryIds.length?'':'quiet'" @click="draft.categoryIds=[];draft.labelIds=[]">全部板块</button><button role="button" v-for="c in categories" :key="c.id" :class="draft.categoryIds.includes(c.id)?'':'quiet'" @click="toggleBoard(c.id)">{{ c.name }}</button></view><text class="field-label">标签（可多选）</text><text v-if="!draft.categoryIds.length" class="muted">先选择板块，再选择该板块下的标签</text><view v-for="board in categories.filter(c=>draft.categoryIds.includes(c.id))" :key="board.id"><text class="field-label">{{ board.name }}</text><view class="tag-grid"><button role="button" v-for="l in visibleLabels.filter(l=>l.categoryId===board.id)" :key="l.id" :class="draft.labelIds.includes(l.id)?'':'quiet'" @click="toggle(l.id)">{{ l.name }}</button></view></view><text class="field-label">关键词（可多选）</text><view class="tag-grid"><button role="button" v-for="k in keywords" :key="k.id" :class="draft.keywordIds.includes(k.id)?'':'quiet'" @click="toggleKeyword(k.id)">{{ k.name }}</button></view><view class="row"><text>启用过期历史信息搜索</text><switch :checked="draft.expired" @change="draft.expired=($event as any).detail.value"/></view><view class="actions"><button role="button" class="quiet" @click="draft={typeCodes:[],categoryIds:[],labelIds:[],keywordIds:[],expired:false}">重置筛选</button><button role="button" :disabled="busy" @click="apply">应用筛选</button></view></view></view><LoginSheet/></view></template>
